from __future__ import annotations
from ledger_core import atomic, fingerprint

def ingest(con, payload):
    required = {
        'site_id', 'parcel_key', 'kind', 'acres', 'documented_mw',
        'utility_ref', 'upgrade_cents', 'upgrade_limit_cents',
        'energization_months', 'schedule_limit_months',
        'zoning_ok', 'fiber_ok', 'water_ok'
    }
    if set(payload) != required:
        raise ValueError('Supply exactly the documented intake fields')
    if payload['kind'] not in ('bess', 'campus'):
        raise ValueError('Choose a battery or campus product')
    for key in ('site_id', 'parcel_key', 'utility_ref'):
        if not isinstance(payload[key], str) or not payload[key].strip():
            raise ValueError('Supply stable identifiers and a utility reference')
    for key in ('upgrade_cents', 'upgrade_limit_cents',
                'energization_months', 'schedule_limit_months'):
        if type(payload[key]) is not int or payload[key] < 0:
            raise ValueError('Cost and schedule fields require nonnegative integers')
    for key in ('acres', 'documented_mw'):
        value = payload[key]
        if type(value) not in (int, float) or not 0 < value < 1000000:
            raise ValueError('Area and capacity require bounded positive numbers')
    for key in ('zoning_ok', 'fiber_ok', 'water_ok'):
        if type(payload[key]) is not bool:
            raise ValueError('Evidence flags require explicit boolean values')
    passed = (
        payload['zoning_ok']
        and payload['upgrade_cents'] <= payload['upgrade_limit_cents']
        and 0 < payload['energization_months'] <= payload['schedule_limit_months']
    )
    if payload['kind'] == 'bess':
        passed = passed and 5 <= payload['acres'] <= 25
    else:
        passed = passed and payload['fiber_ok'] and payload['water_ok']
    digest = fingerprint(payload)
    with atomic(con):
        existing = con.execute(
            'SELECT * FROM site WHERE site_id = ?',
            (payload['site_id'],)
        ).fetchone()
        if existing:
            if existing['input_hash'] != digest:
                raise ValueError('Intake replay changed the original payload')
            return dict(existing)
        con.execute(
            'INSERT INTO site(site_id,parcel_key,input_hash,kind,state) '
            'VALUES (?,?,?,?,?)',
            (payload['site_id'], payload['parcel_key'], digest,
             payload['kind'], 'screened' if passed else 'scrubbed')
        )
        return dict(con.execute(
            'SELECT * FROM site WHERE site_id = ?',
            (payload['site_id'],)
        ).fetchone())

from __future__ import annotations
import json
import time
from ledger_core import atomic, fingerprint

ALLOWED = {
    'screened': {'verified', 'scrubbed', 'expired'},
    'verified': {'escrow_ready', 'scrubbed', 'expired'},
    'escrow_ready': {'closed', 'scrubbed', 'expired'},
    'closed': set(), 'scrubbed': set(), 'expired': set()
}

def attest(con, site_id, kind, digest, reviewer, valid_until):
    if len(digest) != 64 or any(c not in '0123456789abcdef' for c in digest):
        raise ValueError('Provide a lowercase SHA256 document digest')
    if not reviewer.strip() or type(valid_until) is not int:
        raise ValueError('Reviewer identity and expiry are required')
    with atomic(con):
        if valid_until <= int(time.time()):
            raise ValueError('Evidence must remain current when recorded')
        row = con.execute(
            'SELECT reviewer,valid_until FROM evidence '
            'WHERE site_id=? AND kind=? AND digest=?',
            (site_id, kind, digest)
        ).fetchone()
        if row:
            if tuple(row) != (reviewer, valid_until):
                raise ValueError('Attestation replay changed its contents')
            return
        con.execute(
            'INSERT INTO evidence(site_id,kind,digest,reviewer,valid_until) '
            'VALUES (?,?,?,?,?)',
            (site_id, kind, digest, reviewer, valid_until)
        )

def transition(con, event_key, site_id, expected_version, target):
    request = [site_id, expected_version, target]
    digest = fingerprint(request)
    with atomic(con):
        prior = con.execute(
            'SELECT * FROM workflow_event WHERE event_key=?', (event_key,)
        ).fetchone()
        if prior:
            if prior['request_hash'] != digest:
                raise ValueError('Transition key was reused with changed content')
            return prior['new_version']
        row = con.execute(
            'SELECT state,version FROM site WHERE site_id=?', (site_id,)
        ).fetchone()
        if row is None or row['version'] != expected_version:
            raise ValueError('Reload the current site version')
        if target not in ALLOWED[row['state']]:
            raise ValueError('This state transition is prohibited')
        needed = set()
        if target in ('verified', 'escrow_ready', 'closed'):
            needed.update(('utility', 'zoning', 'title'))
        if target in ('escrow_ready', 'closed'):
            needed.update(('executed_option', 'escrow_instructions'))
        if target == 'closed':
            needed.add('closing_statement')
        current = {
            item['kind'] for item in con.execute(
                'SELECT kind FROM evidence WHERE site_id=? AND valid_until>?',
                (site_id, int(time.time()))
            )
        }
        if not needed <= current:
            raise ValueError('Current reviewed evidence is incomplete')
        version = expected_version + 1
        changed = con.execute(
            'UPDATE site SET state=?,version=? WHERE site_id=? AND version=?',
            (target, version, site_id, expected_version)
        ).rowcount
        if changed != 1:
            raise RuntimeError('Version comparison failed')
        con.execute(
            'INSERT INTO workflow_event VALUES (?,?,?,?,?)',
            (event_key, site_id, digest, target, version)
        )
        body = json.dumps(
            {'site_id': site_id, 'target': target, 'version': version},
            sort_keys=True
        )
        con.execute(
            'INSERT INTO outbox(event_key,body) VALUES (?,?)',
            (event_key, body)
        )
        return version

from __future__ import annotations
from ledger_core import atomic

def match_bank(con, statement_key, journal_key, cents):
    if type(cents) is not int or cents == 0:
        raise ValueError('Statement amounts require nonzero integer cents')
    with atomic(con):
        prior = con.execute(
            'SELECT journal_key,amount_cents FROM bank_line WHERE statement_key=?',
            (statement_key,)
        ).fetchone()
        if prior:
            if tuple(prior) != (journal_key, cents):
                raise ValueError('Statement replay changed its transaction match')
            return
        row = con.execute(
            'SELECT debit_account,credit_account,amount_cents '
            'FROM journal WHERE event_key=?', (journal_key,)
        ).fetchone()
        if row is None:
            raise ValueError('Post the documented journal event first')
        movement = (
            row['amount_cents'] if row['debit_account'] == 'cash'
            else -row['amount_cents'] if row['credit_account'] == 'cash'
            else 0
        )
        if movement != cents:
            raise ValueError('Bank movement differs from the cash journal event')
        con.execute(
            'INSERT INTO bank_line VALUES (?,?,?)',
            (statement_key, journal_key, cents)
        )

def report(con):
    with atomic(con):
        months = [dict(row) for row in con.execute(
            'SELECT * FROM monthly_reconciliation ORDER BY month'
        )]
        for row in months:
            row['profit_cents'] = row['revenue_cents'] - row['expense_cents']
        balances = [dict(row) for row in con.execute(
            'SELECT * FROM account_balance ORDER BY code'
        )]
        return {'months': months, 'balances': balances}

from __future__ import annotations
from ledger_core import atomic

def quality_check(con):
    with atomic(con):
        integrity = [row[0] for row in con.execute('PRAGMA integrity_check')]
        if integrity != ['ok']:
            raise ValueError('Database integrity check failed')
        if con.execute('PRAGMA foreign_key_check').fetchone():
            raise ValueError('A foreign key check failed')
        total = con.execute(
            'SELECT SUM(debit_balance_cents) FROM account_balance'
        ).fetchone()[0]
        if total != 0:
            raise ValueError('The trial balance does not balance')
        missing = con.execute(
            "SELECT j.event_key FROM journal j LEFT JOIN bank_line b "
            "ON b.journal_key=j.event_key WHERE "
            "(j.debit_account='cash' OR j.credit_account='cash') "
            "AND b.statement_key IS NULL"
        ).fetchall()
        if missing:
            raise ValueError('Cash journal events remain unmatched')
        mismatch = con.execute(
            "SELECT b.statement_key FROM bank_line b JOIN journal j "
            "ON j.event_key=b.journal_key WHERE b.amount_cents <> "
            "CASE WHEN j.debit_account='cash' THEN j.amount_cents "
            "WHEN j.credit_account='cash' THEN -j.amount_cents ELSE 0 END"
        ).fetchone()
        if mismatch:
            raise ValueError('A statement amount differs from its journal event')
        cash = con.execute(
            "SELECT debit_balance_cents FROM account_balance WHERE code='cash'"
        ).fetchone()[0]
        bank = con.execute(
            'SELECT COALESCE(SUM(amount_cents),0) FROM bank_line'
        ).fetchone()[0]
        if cash != bank:
            raise ValueError('Cash and imported statement movements differ')
        return {'cash_cents': cash, 'trial_balance_cents': total}

def dispatch_one(con, receiver):
    if getattr(receiver, 'supports_persistent_idempotency', False) is not True:
        raise ValueError('Receiver must persistently deduplicate event keys')
    with atomic(con):
        row = con.execute(
            'SELECT event_key,body FROM outbox WHERE delivered=0 '
            'ORDER BY event_key LIMIT 1'
        ).fetchone()
        if row is None:
            return False
        accepted = receiver(
            row['body'], idempotency_key=row['event_key']
        )
        if accepted is not True:
            raise RuntimeError('Receiver did not confirm durable acceptance')
        con.execute(
            'UPDATE outbox SET delivered=1 WHERE event_key=?',
            (row['event_key'],)
        )
        return True
